<template><div class="page-shell"><section class="page-heading"><div><p class="eyebrow">Autonomous tasks / 10</p><h2>Sequences</h2><p>Orchestrate repeatable missions and monitor autonomous execution.</p></div><div class="page-actions"><button class="tesla-btn">Import</button><button class="tesla-btn">Export</button><button class="tesla-btn-primary" @click="running=!running">{{ running ? 'Pause all' : 'Run selected' }}</button></div></section><div class="metric-grid sequences-metrics"><div class="metric-tile"><span>Active sequences</span><strong>{{ sequences.filter(s=>s.status==='running').length }}</strong></div><div class="metric-tile"><span>Progress</span><strong>{{ progress }}%</strong></div><div class="metric-tile"><span>Success rate</span><strong>96.2%</strong></div><div class="metric-tile"><span>Active tasks</span><strong>{{ tasks.length }}</strong></div></div><div class="page-grid two"><article class="data-card"><div class="card-header"><h3>Available sequences</h3><button class="tesla-btn-primary" @click="addSequence"><Plus :size="15"/> New</button></div><div class="sequence-list"><button v-for="sequence in sequences" :key="sequence.id" class="sequence-row" :class="{selected:selected===sequence.id}" @click="selected=sequence.id"><span class="sequence-icon"><FolderOpen :size="16"/></span><span class="control-label"><strong>{{ sequence.name }}</strong><small>{{ sequence.description }}</small></span><span class="status-pill" :class="sequence.status==='running'?'active':'success'">{{ sequence.status }}</span><Play :size="16"/></button></div></article><article class="data-card"><div class="card-header"><h3>Execution logs</h3><span class="status-pill active">Streaming</span></div><div class="log-list"><div v-for="log in logs" :key="log.time" class="log-row"><span>{{ log.time }}</span><b>{{ log.level }}</b><p>{{ log.message }}</p></div></div></article></div><article class="data-card tasks-card"><div class="card-header"><div><p class="eyebrow">Selected sequence</p><h3>{{ selectedSequence.name }}</h3></div><button class="tesla-btn">Add task</button></div><div v-for="(task,index) in tasks" :key="task.name" class="control-row"><span class="task-number">{{ String(index+1).padStart(2,'0') }}</span><span class="control-label"><strong>{{ task.name }}</strong><small>{{ task.detail }}</small></span><span class="status-pill" :class="task.status==='completed'?'success':'active'">{{ task.status }}</span><button class="icon-button-small" @click="task.status=task.status==='completed'?'running':'completed'"><Check :size="14"/></button></div></article></div></template>
<script setup lang="ts">import { computed, ref } from 'vue'; import { Check, FolderOpen, Play, Plus } from 'lucide-vue-next'; const selected=ref('patrol');const running=ref(false);const sequences=ref([{id:'patrol',name:'Security patrol route',description:'Comprehensive perimeter coverage',status:'running'},{id:'maintenance',name:'Maintenance inspection',description:'Automated system health verification',status:'idle'},{id:'recognition',name:'Object recognition',description:'AI-powered anomaly identification',status:'idle'}]);const tasks=ref([{name:'Navigate to checkpoint Alpha',detail:'Optimal path planning',status:'completed'},{name:'Scan environment',detail:'360-degree environmental scan',status:'running'},{name:'Return to base',detail:'Docking station approach',status:'idle'}]);const logs=[{time:'14:32:15',level:'INFO',message:'Navigate to checkpoint completed successfully'},{time:'14:31:42',level:'INFO',message:'Starting environmental scan procedure'},{time:'14:31:15',level:'WARN',message:'Obstacle detected, recalculating path'},{time:'14:30:58',level:'INFO',message:'Security patrol route initiated'}];const selectedSequence=computed(()=>sequences.value.find(s=>s.id===selected.value)||sequences.value[0]);const progress=computed(()=>tasks.value.filter(t=>t.status==='completed').length/tasks.value.length*100);const addSequence=()=>sequences.value.push({id:`new-${Date.now()}`,name:'New sequence',description:'Untitled autonomous workflow',status:'idle'})</script>
<style scoped>.sequences-metrics{margin-top:22px}.sequence-list{display:grid;gap:7px}.sequence-row{display:flex;width:100%;align-items:center;gap:11px;padding:13px;color:var(--ink);background:transparent;border:1px solid var(--line);text-align:left;cursor:pointer}.sequence-row:hover,.sequence-row.selected{background:var(--surface-soft);border-color:var(--line-strong)}.sequence-icon{display:grid;width:32px;height:32px;place-items:center;background:var(--surface-soft)}.sequence-row .control-label{flex:1}.sequence-row>svg:last-child{color:var(--ink-muted)}.tasks-card{margin-top:18px}.task-number{width:25px;color:var(--ink-muted);font:10px 'DM Mono',monospace}.icon-button-small{display:grid;width:28px;height:28px;place-items:center;color:var(--ink);background:var(--surface-soft);border:1px solid var(--line);cursor:pointer}</style>
